update public.qualification_requirements q set title='A-42 Aeronautical knowledge test', regulation_citation='14 CFR §§ 61.35(a)(1) and 61.65(a) and (b).', display_config=jsonb_set(q.display_config,'{required_text}','"I certify that [First name, MI, Last name] has received the required training of 14 CFR \u00a7 61.65(b). I have determined that they are prepared for the Instrument\u2013[airplane, helicopter, or powered-lift] knowledge test."'::jsonb) from public.qualification_rule_sets r where r.id=q.rule_set_id and r.code like 'INSTRUMENT_AIRPLANE_PART61_%' and q.requirement_code='IR_ENDORSEMENT_KNOWLEDGE';
update public.qualification_requirements q set title='A-43 Flight proficiency/practical test', regulation_citation='14 CFR § 61.65(a)(6).', display_config=jsonb_set(q.display_config,'{required_text}','"I certify that [First name, MI, Last name] has received the required training of 14 CFR \u00a7 61.65(c) and (d). I have determined they are prepared for the Instrument\u2013[airplane, helicopter, or powered-lift] practical test."'::jsonb) from public.qualification_rule_sets r where r.id=q.rule_set_id and r.code like 'INSTRUMENT_AIRPLANE_PART61_%' and q.requirement_code='IR_ENDORSEMENT_PRACTICAL';
update public.qualification_requirements q set title='A-44 Prerequisites for instrument practical tests', regulation_citation='14 CFR § 61.39(a).', display_config=jsonb_set(q.display_config,'{required_text}','"I certify that [First name, MI, Last name] has received and logged the required flight time/training of 14 CFR \u00a7 61.39(a) in preparation for the practical test within 2 calendar months preceding the date of the test and has satisfactory knowledge of the subject areas in which they were shown to be deficient by the FAA Airman Knowledge Test Report. I have determined they are prepared for the Instrument\u2013[airplane, helicopter, or powered-lift] practical test."'::jsonb) from public.qualification_rule_sets r where r.id=q.rule_set_id and r.code like 'INSTRUMENT_AIRPLANE_PART61_%' and q.requirement_code='IR_ENDORSEMENT_PREREQUISITES';
